"""Educational Medication Administration Record (MAR) tooling.

Invented drugs only -- this is a teaching/demo tool, not clinical software.

All work is done in UTC with plain ``datetime`` objects; no timezone libraries.
"""

from datetime import datetime, timedelta
from itertools import cycle, islice

# Inline frequency table: frequency code -> administration clock times (UTC).
FREQUENCIES = {
    "QD": ["08:00"],
    "BID": ["08:00", "20:00"],
    "TID": ["08:00", "14:00", "20:00"],
    "QID": ["06:00", "12:00", "18:00", "22:00"],
    "Q6H": ["00:00", "06:00", "12:00", "18:00"],
    "Q8H": ["06:00", "14:00", "22:00"],
}


class UnknownFrequencyError(ValueError):
    """Raised when a frequency code is not in the table."""


def _parse_hhmm(s):
    h, m = s.split(":")
    return int(h), int(m)


def schedule(drug, freq, start_dt, days):
    """Return the administration schedule for ``drug`` at frequency ``freq``.

    The first administration is the first daily slot at or after ``start_dt``;
    the returned list contains exactly ``days`` * slots-per-day datetimes,
    strictly increasing, all in UTC.
    """
    if freq not in FREQUENCIES:
        valid = ", ".join(sorted(FREQUENCIES))
        raise UnknownFrequencyError(
            f"unknown frequency {freq!r} for drug {drug!r}; valid options: {valid}"
        )
    if not isinstance(start_dt, datetime):
        raise TypeError("start_dt must be a datetime")
    if days < 1:
        raise ValueError("days must be >= 1")

    slots = FREQUENCIES[freq]
    base_date = start_dt.date()

    # Infinite stream of slot datetimes starting on start_dt's date.
    def stream():
        day = base_date
        while True:
            for hhmm in slots:
                h, m = _parse_hhmm(hhmm)
                yield datetime(day.year, day.month, day.day, h, m)
            day += timedelta(days=1)

    # Skip slots strictly before start_dt, then take days * len(slots) stamps.
    stamps = islice((dt for dt in stream() if dt >= start_dt), days * len(slots))
    return list(stamps)


# A tiny invented formulary so the CLI/tests read like a real MAR.
FORMULARY = {
    "Zorvaflox": "fictional fluoroquinolone (teaching example)",
    "Nimbralin": "fictional NSAID (teaching example)",
    "Quentavir": "fictional antiviral (teaching example)",
}


def per_day_grid(drug, freq, start_dt, days):
    """Render the schedule as a per-day grid string."""
    lines = [
        f"MAR (educational) -- {drug} @ {freq}, "
        f"{days} day(s), starting {start_dt.isoformat()} UTC"
    ]
    if drug in FORMULARY:
        lines.append(f"# {FORMULARY[drug]}")
    lines.append("")
    current_day = None
    for dt in schedule(drug, freq, start_dt, days):
        if dt.date() != current_day:
            current_day = dt.date()
            lines.append(f"{current_day.isoformat()} (UTC)")
        lines.append(f"  {dt.strftime('%H:%M')}  [ ] administer")
    return "\n".join(lines)


def main(argv=None):
    import argparse

    p = argparse.ArgumentParser(description="Educational MAR schedule printer")
    p.add_argument("drug", help="drug name")
    p.add_argument(
        "freq",
        choices=sorted(FREQUENCIES),
        help="administration frequency code",
    )
    p.add_argument("start", help="start datetime UTC, e.g. 2026-08-24T07:30")
    p.add_argument("--days", type=int, default=3)
    args = p.parse_args(argv)

    start_dt = datetime.fromisoformat(args.start)
    print(per_day_grid(args.drug, args.freq, start_dt, args.days))


if __name__ == "__main__":
    main()

from datetime import datetime

import pytest

from med_schedule import FREQUENCIES, UnknownFrequencyError, schedule


def test_bid_start_0730_first_dose_same_day_0800():
    stamps = schedule("Zorvaflox", "BID", datetime(2026, 8, 24, 7, 30), 3)
    assert stamps[0] == datetime(2026, 8, 24, 8, 0)


def test_bid_start_2100_first_dose_next_day_2000():
    stamps = schedule("Zorvaflox", "BID", datetime(2026, 8, 24, 21, 0), 3)
    assert stamps[0] == datetime(2026, 8, 25, 20, 0)


def test_q6h_from_midnight_three_days():
    stamps = schedule("Nimbralin", "Q6H", datetime(2026, 8, 24, 0, 0), 3)
    assert len(stamps) == 4 * 3 == 12
    assert stamps[-1] == datetime(2026, 8, 26, 18, 0)
    assert stamps == [
        datetime(2026, 8, 24, h % 24, 0) for h, _ in enumerate(range(12), start=0)
    ]


@pytest.mark.parametrize("freq,slots", sorted(FREQUENCIES.items()))
def test_slots_match_table_exactly(freq, slots):
    start = datetime(2026, 1, 10, 9, 15)  # mid-day start to exercise rollover
    stamps = schedule("Quentavir", freq, start, 5)
    expected_minutes = {int(h) * 60 + int(m) for h, m in (s.split(":") for s in slots)}
    for a, b in zip(stamps, stamps[1:]):
        assert a < b, f"stamps not strictly increasing for {freq}: {a} !< {b}"
    for dt in stamps:
        assert dt.hour * 60 + dt.minute in expected_minutes


@pytest.mark.parametrize("freq,slots", sorted(FREQUENCIES.items()))
def test_count_formula_all_frequencies(freq, slots):
    for days in (1, 2, 3, 7):
        stamps = schedule("Zorvaflox", freq, datetime(2026, 5, 1, 13, 45), days)
        assert len(stamps) == days * len(slots)
        # first stamp is the first slot at or after start
        first_slot_today = [
            datetime(2026, 5, 1, int(s[:2]), int(s[3:])) for s in slots
        ]
        eligible = [d for d in first_slot_today if d >= datetime(2026, 5, 1, 13, 45)]
        assert stamps[0] == (
            eligible[0]
            if eligible
            else datetime(2026, 5, 2, int(slots[0][:2]), int(slots[0][3:]))
        )


def test_unknown_frequency_raises_with_valid_options():
    with pytest.raises(UnknownFrequencyError) as exc:
        schedule("Zorvaflox", "TIDS", datetime(2026, 8, 24, 8, 0), 1)
    msg = str(exc.value)
    for option in FREQUENCIES:
        assert option in msg


def test_exact_boundary_start_on_slot_counts_that_slot():
    stamps = schedule("Zorvaflox", "BID", datetime(2026, 8, 24, 20, 0), 2)
    assert stamps[0] == datetime(2026, 8, 24, 20, 0)

